import{_ as a,a0 as r,w as p,s as d,I as t,x as n,a1 as e,A as o,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const E=JSON.parse('{"title":"在 Linux 上運行你最喜歡的 Windows 應用程序 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上運行你最喜歡的 Windows 應用程序 | LCTT (202103) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上運行你最喜歡的 Windows 應用程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上運行你最喜歡的 Windows 應用程序 | LCTT (202103) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202103/20210220 Run your favorite Windows applications on Linux","title":"在 Linux 上運行你最喜歡的 Windows 應用程序","tag":"202103","desc":""},"relativePath":"202103/20210220 Run your favorite Windows applications on Linux.md","filePath":"[post].md"}'),u={name:"202103/20210220 Run your favorite Windows applications on Linux.md"};function w(W,i,f,m,x,g){const s=r("Link");return p(),d("div",null,[i[27]||(i[27]=t("h1",{id:"在-linux-上運行你最喜歡的-windows-應用程序",tabindex:"-1"},[n("在 Linux 上運行你最喜歡的 Windows 應用程序 "),t("a",{class:"header-anchor",href:"#在-linux-上運行你最喜歡的-windows-應用程序","aria-label":"Permalink to “在 Linux 上運行你最喜歡的 Windows 應用程序”"},"​")],-1)),i[28]||(i[28]=t("blockquote",null,[t("p",null,"WINE 是一個開源項目，它可以協助很多 Windows 應用程序在 Linux 上運行，就好像它們是原生程序一樣。")],-1)),i[29]||(i[29]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202103/07/231159kwsn2snlilwbs9ns.jpg",alt:""})],-1)),i[30]||(i[30]=t("p",null,"在 2021 年，有很多比以往更喜歡 Linux 的原因。在這系列中，我將分享使用 Linux 的 21 種原因。這裏是如何使用 WINE 來實現從 Windows 到 Linux 的無縫切換。",-1)),i[31]||(i[31]=t("p",null,"你有隻能在 Windows 上運行的應用程序嗎？那一個應用程序阻礙你切換到 Linux 的唯一因素嗎？如果是這樣的話，你將會很高興知道 WINE，這是一個開源項目，它幾乎重新發明了關鍵的 Windows 庫，使為 Windows 編譯的應用程序可以在 Linux 上運行。",-1)),t("p",null,[i[1]||(i[1]=n("WINE 代表着“Wine Is Not an Emulator” ，它指的是驅動這項技術的代碼。開源開發者從 1993 年就開始致力將應用程序的任何傳入 Windows API 調用翻譯為 ",-1)),e(s,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:o(()=>[...i[0]||(i[0]=[n("POSIX",-1)])]),_:1}),i[2]||(i[2]=n(" 調用。",-1))]),t("p",null,[i[6]||(i[6]=n("這是一個令人十分驚訝的編程壯舉，尤其是考慮到這個項目是獨立運行的，沒有來自微軟的幫助（至少可以這樣説），但是也有侷限性。一個應用程序偏離 Windows API 的 “內核” 越遠，WINE 就越不能預期應用程序的請求。有一些供應商可以彌補這一點，尤其是 ",-1)),e(s,{href:"https://www.codeweavers.com/crossover"},{default:o(()=>[...i[3]||(i[3]=[n("Codeweavers",-1)])]),_:1}),i[7]||(i[7]=n(" 和 ",-1)),e(s,{href:"https://github.com/ValveSoftware/Proton"},{default:o(()=>[...i[4]||(i[4]=[n("Valve Software",-1)])]),_:1}),i[8]||(i[8]=n("。在需要翻譯應用程序的製作者和翻譯的人們及公司之間沒有協調配合，因此，比如説一個更新的軟件作品和從 ",-1)),e(s,{href:"http://winehq.org"},{default:o(()=>[...i[5]||(i[5]=[n("WINE 總部",-1)])]),_:1}),i[9]||(i[9]=n(" 獲得完美適配狀態之間可能會有一些時間上的滯後。",-1))]),i[32]||(i[32]=l('<p>然而，如果你想在 Linux 上運行一個著名的 Windows 應用程序，WINE 可能已經為它準備好了可能性。</p><h3 id="安裝-wine" tabindex="-1">安裝 WINE <a class="header-anchor" href="#安裝-wine" aria-label="Permalink to “安裝 WINE”">​</a></h3><p>你可以從你的 Linux 發行版的軟件包存儲庫中安裝 WINE 。在 Fedora、CentOS Stream 或 RHEL 系統上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install wine</span></span></code></pre></div><p>在 Debian、Linux Mint、Elementary 及相似的系統上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install wine</span></span></code></pre></div><p>WINE 不是一個你自己啓動的應用程序。當啓動一個 Windows 應用程序時，它是一個被調用的後端。你與 WINE 的第一次交互很可能就發生在你啓動一個 Windows 應用程序的安裝程序時。</p><h3 id="安裝一個應用程序" tabindex="-1">安裝一個應用程序 <a class="header-anchor" href="#安裝一個應用程序" aria-label="Permalink to “安裝一個應用程序”">​</a></h3>',8)),t("p",null,[e(s,{href:"https://sourceforge.net/projects/tinycad/"},{default:o(()=>[...i[10]||(i[10]=[n("TinyCAD",-1)])]),_:1}),i[11]||(i[11]=n(" 是一個極好的用於設計電路的開源應用程序，但是它僅在 Windows 上可用。雖然它是一個小型的應用程序，但是它確實包含一些 .NET 組件，因此應該能對 WINE 進行一些壓力測試。",-1))]),i[33]||(i[33]=l('<p>首先，下載 TinyCAD 的安裝程序。Windows 安裝程序通常都是這樣，它是一個 <code>.exe</code> 文件。在下載後，雙擊文件來啓動它。</p><p><img src="https://opensource.com/sites/default/files/wine-tinycad-install.jpg" alt="WINE TinyCAD 安裝嚮導"></p><p><em>TinyCAD 的 WINE 安裝嚮導</em></p><p>像你在 Windows 上一樣逐步完成安裝程序。通常最好接受默認選項，尤其是與 WINE 有關的地方。WINE 環境基本上是獨立的，隱藏在你的硬盤驅動器上的一個 <code>drive_c</code> 目錄中，作為 Windows 應用程序使用的一個文件系統的仿真根目錄。</p><p><img src="https://opensource.com/sites/default/files/wine-tinycad-drive_0.jpg" alt="WINE TinyCAD 安裝和目標驅動器"></p><p><em>WINE TinyCAD 目標驅動器</em></p><p>安裝完成後，應用程序通常會為你提供啓動機會。如果你正準備測試一下它的話，啓動應用程序。</p><h3 id="啓動-windows-應用程序" tabindex="-1">啓動 Windows 應用程序 <a class="header-anchor" href="#啓動-windows-應用程序" aria-label="Permalink to “啓動 Windows 應用程序”">​</a></h3><p>除了在安裝後的第一次啓動外，在正常情況下，你啓動一個 WINE 應用程序的方式與你啓動一個本地 Linux 應用程序相同。不管你使用應用程序菜單、活動屏幕或者只是在運行器中輸入應用程序的名稱，在 WINE 中運行的桌面 Windows 應用程序都會被視為在 Linux 上的本地應用程序。</p><p><img src="https://opensource.com/sites/default/files/wine-tinycad-running.jpg" alt="TinyCAD 使用 WINE 運行"></p><p><em>通過 WINE 的支持來運行 TinyCAD</em></p><h3 id="當-wine-失敗時" tabindex="-1">當 WINE 失敗時 <a class="header-anchor" href="#當-wine-失敗時" aria-label="Permalink to “當 WINE 失敗時”">​</a></h3><p>我在 WINE 中的大多數應用程序，包括 TinyCAD ，都能如期運行。不過，也會有例外。在這些情況下，你可以等幾個月來查看 WINE 開發者 （或者，如果是一款遊戲，就等候 Valve Software）是否進行追加修補，或者你可以聯繫一個像 Codeweavers 這樣的供應商來查看他們是否出售對你所需要的應用程序的服務支持。</p><h3 id="wine-是種欺騙-但它用於正道" tabindex="-1">WINE 是種欺騙，但它用於正道 <a class="header-anchor" href="#wine-是種欺騙-但它用於正道" aria-label="Permalink to “WINE 是種欺騙，但它用於正道”">​</a></h3><p>一些 Linux 用户覺得：如果你使用 WINE 的話，你就是在“欺騙” Linux。它可能會讓人有這種感覺，但是 WINE 是一個開源項目，它使用户能夠切換到 Linux ，並且仍然能夠運行工作或愛好所需的應用程序。如果 WINE 解決了你的問題，讓你使用 Linux，那就使用它，並擁抱 Linux 的靈活性。</p><hr>',16)),t("p",null,[i[13]||(i[13]=n("via: ",-1)),e(s,{href:"https://opensource.com/article/21/2/linux-wine"},{default:o(()=>[...i[12]||(i[12]=[n("https://opensource.com/article/21/2/linux-wine",-1)])]),_:1})]),t("p",null,[i[18]||(i[18]=n("作者：",-1)),e(s,{href:"https://opensource.com/users/seth"},{default:o(()=>[...i[14]||(i[14]=[n("Seth Kenlon",-1)])]),_:1}),i[19]||(i[19]=n(" 選題：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...i[15]||(i[15]=[n("lujun9972",-1)])]),_:1}),i[20]||(i[20]=n(" 譯者：",-1)),e(s,{href:"https://github.com/robsean"},{default:o(()=>[...i[16]||(i[16]=[n("robsean",-1)])]),_:1}),i[21]||(i[21]=n(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:o(()=>[...i[17]||(i[17]=[n("wxy",-1)])]),_:1})]),t("p",null,[i[24]||(i[24]=n("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[22]||(i[22]=[n("LCTT",-1)])]),_:1}),i[25]||(i[25]=n(" 原創編譯，",-1)),e(s,{href:"https://linux.cn/"},{default:o(()=>[...i[23]||(i[23]=[n("Linux中國",-1)])]),_:1}),i[26]||(i[26]=n(" 榮譽推出",-1))])])}const T=a(u,[["render",w]]);export{E as __pageData,T as default};
